  {"workspace_id":null,"slug":"bcaa-powder","name_ar":"بي سي ايه ايه بودرة","name_en":"BCAA powder, pure unflavoured free amino acids","category":"supplement","state":"dry","calories_kcal_per_100g":400,"protein_g_per_100g":100,"carbs_g_per_100g":0,"fat_g_per_100g":0,"fiber_g_per_100g":0,"origin":"seed","origin_note":"calculated from composition: Pure unflavoured free-amino-acid BCAA blend: leucine 50%, isoleucine 25%, valine 25%. Manufacturer ingredient basis: https://www.myprotein.com/p/sports-nutrition/essential-bcaa-2-1-1-powder/12456308/. Uses approximately 4 kcal per gram free amino acids, the conventional amino-acid energy factor illustrated by ASHP nutrition-support materials: https://www.ashp.org/-/media/assets/pharmacy-practice/resource-centers/Clinical-Pharmacy-Resources/Nutrition-Support/2016-MCM/MCM16-335-Strategies-for-Successful-Parenteral-nutrition.pdf. This is an explicit tracking convention applied to an oral pure powder, not measured calorimetry, a product-label protein claim, or a nitrogen-derived protein equivalent. protein_g records free amino acid mass as a protein-equivalent tracking proxy so the energy is represented; it is not intact protein and BCAA is not a complete protein. Carbohydrate, fat and fibre are zero by the specified pure composition. Flavoured, instantized lecithin, hydrochloride-salt and diluted products require their own composition; this profile does not apply to them. Actual amino acid energy factors differ. Sources accessed/extracted 2026-10-31.","confidence":"low","review_flags":["brand_varies","composition_defined","pure_product_only","free_amino_acids","protein_equivalent_not_intact_protein","energy_factor_assumed"],"usda_fdc_id":null,"is_verified":false,"entry_basis":"per_100g","is_active":true,"portions":[{"name_ar":"حصة بودرة موزونة","weight_g":5,"is_default":true}],"aliases":[{"kind":"alias_ar","alias":"احماض امينية متفرعة السلسلة بودرة"},{"kind":"alias_ar","alias":"بي سي دبل ايه بودرة"},{"kind":"alias_en","alias":"