  {"workspace_id":null,"slug":"electrolyte-powder","name_ar":"بودرة املاح","name_en":"Electrolyte powder, plain inorganic mineral salts only","category":"supplement","state":"dry","calories_kcal_per_100g":0,"protein_g_per_100g":0,"carbs_g_per_100g":0,"fat_g_per_100g":0,"fiber_g_per_100g":0,"origin":"seed","origin_note":"Composition-defined unflavoured inorganic mineral-salt electrolyte powder ONLY. Manufacturer ingredient example: Bulk Electrolyte Powder unflavoured https://www.bulk.com/uk/products/electrolyte-powder/bpb-elec-0000?pid=3535 (sodium chloride, potassium sulphate, dicalcium phosphate, magnesium oxide). These inorganic salts contain no protein, carbohydrate, fat or dietary fibre and supply no food energy; zeros are chemical-composition inferences, not inferred from absent labels. Ratios are not fixed for generic products: sodium, calcium and potassium stay null. Not applicable to sugar, dextrose, citrate, amino-acid-chelate, coconut-water or flavoured mixes. Generic slug retained with explicitly narrowed display name. Source 2 g dry serving is a bookkeeping portion, not a generic electrolyte dose. Sources accessed/extracted 2026-10-31.","confidence":"medium","review_flags":["brand_varies","composition_defined","inorganic_salts_only","mineral_ratios_unknown"],"usda_fdc_id":null,"is_verified":false,"entry_basis":"per_100g","is_active":true,"portions":[{"name_ar":"حصة املاح سادة موزونة ٢ جرام","weight_g":2,"is_default":true}],"aliases":[{"kind":"alias_ar","alias":"مسحوق الكتروليت"},{"kind":"alias_ar","alias":"بودرة الكترولايت"},{"kind":"alias_en","alias":"electrolyte drink powder"},{"kind":"alias_en","alias":"electrolyte mix"},{"kind":"search_hint","alias":"مكملات"},{"kind":"search_hint","alias":"جاف"},{"kind":"search_hint","alias":"ناشف"}],"nutrients":[]},
