]$seed_foods$::jsonb)
AS d(workspace_id uuid, slug text, name_ar text, name_en text, category text, state text, calories_kcal_per_100g numeric, protein_g_per_100g numeric, carbs_g_per_100g numeric, fat_g_per_100g numeric, fiber_g_per_100g numeric, origin text, origin_note text, confidence text, review_flags text[], usda_fdc_id integer, is_verified boolean, entry_basis text, is_active boolean, portions jsonb, aliases jsonb, nutrients jsonb);
--> statement-breakpoint
INSERT INTO foods (workspace_id, slug, name_ar, name_en, category, state, calories_kcal_per_100g, protein_g_per_100g, carbs_g_per_100g, fat_g_per_100g, fiber_g_per_100g, origin, origin_note, confidence, review_flags, usda_fdc_id, is_verified, entry_basis, is_active)
SELECT workspace_id, slug, name_ar, name_en, category, state, calories_kcal_per_100g, protein_g_per_100g, carbs_g_per_100g, fat_g_per_100g, fiber_g_per_100g, origin, origin_note, confidence, review_flags, usda_fdc_id, is_verified, entry_basis, is_active FROM pg_temp.nutrition_seed_foods WHERE true
ON CONFLICT (slug) WHERE workspace_id IS NULL DO UPDATE SET
  name_ar = EXCLUDED.name_ar,
  name_en = EXCLUDED.name_en,
  category = EXCLUDED.category,
  state = EXCLUDED.state,
  calories_kcal_per_100g = EXCLUDED.calories_kcal_per_100g,
  protein_g_per_100g = EXCLUDED.protein_g_per_100g,
  carbs_g_per_100g = EXCLUDED.carbs_g_per_100g,
  fat_g_per_100g = EXCLUDED.fat_g_per_100g,
  fiber_g_per_100g = EXCLUDED.fiber_g_per_100g,
  origin = EXCLUDED.origin,
  origin_note = EXCLUDED.origin_note,
  confidence = EXCLUDED.confidence,
  review_flags = EXCLUDED.review_flags,
  usda_fdc_id = EXCLUDED.usda_fdc_id,
  is_verified = EXCLUDED.is_verified,
  entry_basis = EXCLUDED.entry_basis,
  is_active = EXCLUDED.is_active;
--> statement-breakpoint
UPDATE foods f SET is_active = false
WHERE f.workspace_id IS NULL AND f.origin = 'estimate'
  AND NOT EXISTS (SELECT 1 FROM pg_temp.nutrition_seed_foods d WHERE d.slug = f.slug);
--> statement-breakpoint
CREATE TEMP TABLE nutrition_seed_recipes ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($seed_recipes$[
  {"workspace_id":null,"slug":"baked-fish-rice-vegetables","name_ar":"سمك في الفرن بالرز والخضار","name_en":"Baked tilapia with rice and vegetables","description_ar":"سمك في الفرن بالرز والخضار بمقادير موزونة؛ الحصة علبة وزنها 590 جرام.","calories_kcal_per_100g":98.13,"protein_g_per_100g":7.72,"carbs_g_per_100g":11.34,"fat_g_per_100g":2.41,"fiber_g_per_100g":0.43,"origin":"seed","origin_note":"Recipe quantities and method checked against https://lauralovinglife.org/baked-tilapia-fresh-veggies-onion-rice/ ; https://loveoffood.sodexo.com/recipe/baked-tilapia-with-basmati-rice/ (accessed 2026-10-31). Sources check baked tilapia with vegetables/rice and oven cooking. Our assumed two-serving version uses zucchini/tomato, plain rice, olive oil and lemon without anchovy butter or onion rice. These are planning adaptations, not a verified prescription from an Egyptian coach. Nutrition is calculated only from the listed out/foods-*.json ingredients and estimated finished weight; source-page nutrition is not copied. All edible oil and sauces listed are counted as eaten; no unlisted caloric garnish.\nYield: Makes 2 serving(s): 2 x 590 g (علبة); finished batch 1180 g. Estimated, not kitchen measured. 1092 g input: fish 400 -> 320 g; rice 140 -> 420 g absorbing 280 g water; zucchini/tomato 500 -> 400 g; oil/lemon/garlic 52 -> 40 g. Retains tray juices and all oil. Two 590 g boxes.","confidence":"low","review_flags":["quantities_vary_by_household","yield_estimated","portion_assumed"],"meal_tags":["lunch","dinner"],"finished_weight_g":1180,"prep_minutes":15,"cook_minutes":30,"youtube_video_id":null,"is_active":true,"portions":[{"name_ar":"علبة","weight_g":590,"is_default":true}],"aliases":[{"kind":"alias_ar","alias":"علبة سمك ورز"}],"ingredients":[{"food_slug":"tilapia-raw","weight_g":400,"note_ar":"فيليه ني صافي من غير جلد أو شوك"},{"food_slug":"rice-white-raw","weight_g":140,"note_ar":"رز جاف"},{"food_slug":"zucchini-raw","weight_g":300,"note_ar":null},{"food_slug":"tomato","wei