WITH desired AS (SELECT p.id AS parent_id, v.name_ar, v.weight_g, v.is_default, a.ordinality::integer AS sort_order
  FROM pg_temp.nutrition_seed_foods d
  JOIN foods p ON p.slug = d.slug AND p.workspace_id IS NULL
  CROSS JOIN LATERAL jsonb_array_elements(d.portions) WITH ORDINALITY AS a(value, ordinality)
  CROSS JOIN LATERAL jsonb_to_record(a.value) AS v(name_ar text, weight_g numeric, is_default boolean)), updated AS (
  UPDATE food_portions c SET weight_g = d.weight_g, is_default = d.is_default, sort_order = d.sort_order
  FROM desired d WHERE c.workspace_id IS NULL AND c.food_id = d.parent_id AND c.name_ar = d.name_ar
  RETURNING c.id
)
