DO $seed_verify$
BEGIN
  IF (SELECT count(*) FROM foods WHERE workspace_id IS NULL AND origin = 'seed' AND is_active) <> 437 THEN
    RAISE EXCEPTION 'Nutrition seed: active food count mismatch';
  END IF;
  IF EXISTS (
    SELECT d.slug FROM pg_temp.nutrition_seed_foods d
    LEFT JOIN foods f ON f.slug = d.slug AND f.workspace_id IS NULL
    LEFT JOIN food_nutrients n ON n.food_id = f.id AND n.workspace_id IS NULL
    GROUP BY d.slug, d.nutrients HAVING count(n.nutrient_id) <> jsonb_array_length(d.nutrients)
  ) THEN RAISE EXCEPTION 'Nutrition seed: nutrient count mismatch (unresolved nutrient code or missing food)'; END IF;
  IF EXISTS (
    SELECT d.slug FROM pg_temp.nutrition_seed_recipes d
    LEFT JOIN recipes r ON r.slug = d.slug AND r.workspace_id IS NULL
    LEFT JOIN recipe_ingredients i ON i.recipe_id = r.id AND i.workspace_id IS NULL
    GROUP BY d.slug, d.ingredients HAVING count(i.id) <> jsonb_array_length(d.ingredients)
  ) THEN RAISE EXCEPTION 'Nutrition seed: ingredient count mismatch (unresolved food slug or missing recipe)'; END IF;
  IF (SELECT count(*) FROM foods f JOIN jsonb_array_elements_text($seed_starters$[
  "apple",
  "banana",
  "beef-lean-cooked",
  "bread-baladi",
  "broccoli-cooked",
  "chicken-breast-grilled",
  "chicken-thigh-grilled",
  "cucumber",
  "egg-boiled",
  "ful-with-oil",
  "lettuce",
  "milk-full-fat",
  "olive-oil",
  "peanut-butter",
  "potato-boiled",
  "rice-white-cooked",
  "spinach-cooked",
  "tomato",
  "tuna-canned-water",
  "whey-protein",
  "yogurt-plain",
  "zucchini-cooked"
]$seed_starters$::jsonb) AS d(slug) ON d.slug = f.slug
      WHERE f.workspace_id IS NULL AND f.is_active) <> 22 THEN
    RAISE EXCEPTION 'Nutrition seed: missing active starter food';
  END IF;
  IF EXISTS (
    SELECT p.id FROM foods p JOIN pg_temp.nutrition_seed_foods d ON d.slug = p.slug
    LEFT JOIN food_portions c ON c.food_id = p.id AND c.workspace_id IS NULL AND c.is_default
    WHERE p.workspace_id IS NULL GROUP BY p.id HAVING count(c.id) <> 1
  ) THEN RAISE EXCEPTION 'Nutrition seed: expected one default portion per foods'; END IF;
  IF EXISTS (
    SELECT p.id FROM recipes p JOIN pg_temp.nutrition_seed_recipes d ON d.slug = p.slug
    LEFT JOIN recipe_portions c ON c.recipe_id = p.id AND c.workspace_id IS NULL AND c.is_default
    WHERE p.workspace_id IS NULL GROUP BY p.id HAVING count(c.id) <> 1
  ) THEN RAISE EXCEPTION 'Nutrition seed: expected one default portion per recipes'; END IF;
END;
$seed_verify$;
